33	/// AC4 — proves the `dio` + `flutter_secure_storage` + `get_it` integration
34	/// spike works together in one bootstrap, before anything else is built on
35	/// top of it (architecture spine's Deferred note).
36	///
37	/// No device/simulator/CI exists yet to run a true platform-channel
38	/// integration test (AGENTS.md's "Running and verifying" TODO), so the
39	/// native secure-storage channel is faked with an in-memory store here —
40	/// the test still exercises the *real* `FlutterSecureStorage` instance
41	/// resolved from the single DI container, round-tripping a write/read
42	/// through it exactly as AC4 requires.
43	void main() {
44	  TestWidgetsFlutterBinding.ensureInitialized();
45	
46	  const secureStorageChannel = MethodChannel(
47	    'plugins.it_nomads.com/flutter_secure_storage',
48	  );
49	  final fakeNativeStorage = <String, String>{};
50	
51	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
52	    final args = call.arguments as Map<dynamic, dynamic>;
53	    switch (call.method) {
54	      case 'write':
55	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
