        // time the next tick would fire — so it's called here too,
        // directly inside the elapsed window.
        unawaited(cubit.close());
        async.flushMicrotasks();

        async.elapse(onePoll);
        expect(repository.getStatusCalls, isEmpty);
      });
    },
  );
}

